extern const u8 *const ov08_022259CC[34];

extern const u8 ov08_022259BC[3];

extern const u8 ov08_022259AC[3];

void RetrieveButtonData(BattleParty *battleParty, u16 *buttonData, u8 button, enum BattleSubMenuButtonState buttonState, u8 isAltButton);

void ov08_022221CC(BattleParty *battleParty, enum BattlePartyScreen screen);

void ov08_02221EE8(BattleParty *battleParty, u8 button, enum BattleSubMenuButtonState buttonState);

void ov08_02221EE8(BattleParty *battleParty, u8 button, enum BattleSubMenuButtonState buttonState) {
    const u8 *windowsToScroll = ov08_022259CC[button];
    u8 scrollDirection, scrollDistance;

    if (windowsToScroll == 0L) {
        return;
    }

    if (button >= BUTTON_POKEMON_PARTY_SCREEN_POKEMON_1 && button <= BUTTON_POKEMON_PARTY_SCREEN_POKEMON_6) {
        scrollDistance = ov08_022259BC[buttonState];
    } else {
        scrollDistance = ov08_022259AC[buttonState];
    }

    switch (buttonState) {
    case BATTLE_SUB_MENU_BUTTON_STATE_UNPRESSED:
        scrollDirection = SCROLL_DIRECTION_DOWN;
        break;
    case BATTLE_SUB_MENU_BUTTON_STATE_PRESSING:
        scrollDirection = SCROLL_DIRECTION_UP;
        break;
    case BATTLE_SUB_MENU_BUTTON_STATE_PRESSED:
        scrollDirection = SCROLL_DIRECTION_DOWN;
        break;
    }

    if (button >= BUTTON_POKEMON_MOVES_SCREEN_MOVE_1 && button <= BUTTON_POKEMON_MOVES_SCREEN_MOVE_4) {
        ScrollWindow(&battleParty->windows[windowsToScroll[battleParty->useAltSummaryWindows]], scrollDirection, scrollDistance, 0);
        ScheduleWindowCopyToVram(&battleParty->windows[windowsToScroll[battleParty->useAltSummaryWindows]]);
    } else {
        for (u16 i = 0; i < 8; i++) {
            if (windowsToScroll[i] == 255) {
                break;
            }

            ScrollWindow(&battleParty->windows[windowsToScroll[i]], scrollDirection, scrollDistance, 0);
            ScheduleWindowCopyToVram(&battleParty->windows[windowsToScroll[i]]);
        }
    }
}
